contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will attempt to Put some Ether, advance nothing (no time travel possible here),
    // then try to Collect some amount. The property: if Collect does not revert and results
    // in an on-chain transfer to this contract's address (msg.sender of c calls is this test),
    // then the reported Acc balance in c decreases by the collected amount and the contract
    // balance of c decreases by same amount.

    function run(uint putLock, uint putAmount, uint collectAmount) public payable {
        require(address(this).balance >= putAmount, "need funds");
        // Ensure contract is in uninitialized state to allow Put and MinSum settings
        // Set a small MinSum so Collect can potentially proceed
        // These setup calls change c's state and must be top-level statements
        c.SetMinSum(1);
        // Deposit into c using Put
        c.Put{value: putAmount}(putLock);

        // Read observable before-values
        (uint beforeBal, uint beforeUnlock) = c.Acc(address(this));
        uint cBalanceBefore = address(c).balance;
        uint minSum = c.MinSum();

        // Try Collect and record whether it reverted
        bool reverted;
        try c.Collect(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-values
        (uint afterBal, uint afterUnlock) = c.Acc(address(this));
        uint cBalanceAfter = address(c).balance;

        // If Collect did not revert and the preconditions for transfer were satisfied
        // according to public getters (balance >= MinSum, balance >= collectAmount, and timestamp > unlockTime)
        // then the holder's balance must have decreased by exactly collectAmount and c's balance decreased same.
        // We cannot observe timestamp>unlockTime directly; we rely on observable beforeUnlock and block.timestamp.

        bool precondsHold = (beforeBal >= minSum) && (beforeBal >= collectAmount) && (block.timestamp > beforeUnlock);

        // General rule: if call succeeded AND preconditions held, balances decreased exactly by collectAmount
        assert(!(reverted == false && precondsHold) || (afterBal + collectAmount == beforeBal && cBalanceBefore == cBalanceAfter + collectAmount));
    }

    receive() external payable { }
}

