contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Try to withdraw `am` via Collect; also provide funds beforehand via Put if forwarding is desired.
    // We take three params: amount to attempt to collect, an amount to fund via Put before collecting, and lockTime for that Put.
    function run(uint am, uint fundAmount, uint lockTime) public payable {
        require(address(this).balance >= fundAmount);

        // Observe c and this before any calls
        (uint unlockBefore, uint balBefore) = c.Acc(address(this));
        uint cBalBefore = address(c).balance;
        uint minSum = c.MinSum();

        // Optionally fund the account by calling Put with fundAmount
        if (fundAmount > 0) {
            // forward funds to c
            c.Put{value: fundAmount}(lockTime);
        }

        // Observe after funding
        (uint unlockMid, uint balMid) = c.Acc(address(this));
        uint cBalMid = address(c).balance;

        // Attempt Collect and record whether it reverted
        bool reverted;
        try c.Collect(am) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe after collect
        (uint unlockAfter, uint balAfter) = c.Acc(address(this));
        uint cBalAfter = address(c).balance;

        // General rule:
        // If Collect did not revert and actually transferred funds (i.e., balMid >= minSum && balMid >= am && block.timestamp > unlockMid),
        // then c's balance must have decreased by exactly am and Acc[this].balance decreased by exactly am.
        // Otherwise, if Collect did not revert but the conditions for transfer weren't met, it must have left balances unchanged.
        // If Collect reverted, nothing is required (it may revert for many reasons).

        // We cannot read block.timestamp here, but we can observe whether a transfer happened by checking c's balance change and Acc change.
        // Encode the assertion accordingly: If not reverted then either balances decreased by am, or balances are unchanged.

        assert(!reverted ? ((cBalAfter + am == cBalMid && balAfter + am == balMid) || (cBalAfter == cBalMid && balAfter == balMid)) : true);
    }

    receive() external payable {}
}

