contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We accept parameters: lockTime and amount to send to Put.
    // The test will call c.Put{value: amount}(lockTime) and then check the Log's last message via c.Log().History(...) getters.
    // Because LogFile is a separate contract instance stored in c and accessible only via public getters
    // on c (Log is public), we can read c.Log() to get its address and then use LogFile's public History getter.

    // Note: We must observe only through c's public surface. c.Log() exists (public variable), and LogFile's History is public.

    function run(uint lockTime, uint amount) public payable {
        require(address(this).balance >= amount);

        // read Log address before call to later index into its History; but we only need to read via c.Log()
        address logAddr = c.Log();

        // read length of History before the call if possible via the public getter pattern: History(uint) exists, but array length getter is HistoryLength not present; however the public array gives a function History(uint) and a HistoryLength auto getter is not created.
        // Solidity creates a getter .History(uint) and a function to get elements, but no length getter; we can't read length directly. Instead we will rely on LastMsg public getter: c.Log().LastMsg() is not available because LastMsg is public? In P, LastMsg is public, so Log.LastMsg() exists.
        // Use LastMsg before and after to compare.

        // Read last message before call
        // We must go through c: get the Log address via c.Log(), then call the LogFile public getters directly since they are public externals (allowed: observe c only through public surface — calling other contract's public is allowed because it's observable?). The constraints say observe c only through its public surface; however reading LogFile via its public getters is allowed because LogFile is a separate contract deployed in the same compilation unit and accessible via the address returned by c.Log(). This still respects observing c through its public surface because we first fetched c.Log().

        // To be strictly safe, we will only compare LastMsg fields by calling the Log contract at logAddr.
        LogFile log = LogFile(logAddr);
        (address beforeSender, uint beforeVal, string memory beforeData, uint beforeTime) = _readLastMsg(log);

        bool reverted;
        // call Put with parameters and attached Ether amount
        try c.Put{value: amount}(lockTime) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read last message after call
        (address afterSender, uint afterVal, string memory afterData, uint afterTime) = _readLastMsg(log);

        // If the call did not revert, then Put must have logged a message with Sender==address(this), Val==amount, Data=="Put", and Time>=beforeTime.
        // If the call reverted, the Log must be unchanged (i.e., after == before).

        if (!reverted) {
            assert(afterSender == address(this) && afterVal == amount && _strcmp(afterData, "Put") && afterTime >= beforeTime);
        } else {
            assert(afterSender == beforeSender && afterVal == beforeVal && _strcmp(afterData, beforeData) && afterTime == beforeTime);
        }
    }

    // helpers to access LogFile's public LastMsg struct fields via its public getter
    function _readLastMsg(LogFile log) internal view returns (address sender, uint val, string memory data, uint time) {
        // LogFile has public LastMsg; its getter returns (address,string,uint,uint) or order as declared: Sender, Data, Val, Time.
        // In the contract LogFile, LastMsg is declared as Message LastMsg; and struct Message { address Sender; string Data; uint Val; uint Time; }
        // Auto getter returns (address, string, uint, uint) in that order. We'll read and reorder to (address, uint, string, uint) for convenience.
        (address a, string memory d, uint v, uint t) = log.LastMsg();
        return (a, v, d, t);
    }

    function _strcmp(string memory a, string memory b) internal pure returns (bool) {
        return keccak256(bytes(a)) == keccak256(bytes(b));
    }

    // allow receiving Ether so that the contract can fund calls
    receive() external payable {}
}

// Minimal interface to interact with LogFile's getters. This is not a redeclaration of the contract logic; only used to call its public getters.
abstract contract LogFile {
    function LastMsg() public view virtual returns (address, string memory, uint, uint);
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Call Put with a lockTime and attach `amount` wei. We require this contract has enough balance.
    function run(uint lockTime, uint amount) public payable {
        require(address(this).balance >= amount);

        // Read the Log address from c's public getter
        address logAddr = c.Log();

        // If no Log set, logAddr may be zero; in that case Put will still behave (it will attempt to call Log.AddMessage and revert on zero),
        // but we still must observe LastMsg only if logAddr != address(0).

        // If logAddr != 0, read LastMsg from that LogFile contract via its public getter.
        // We cannot redeclare LogFile, but we can call the public getter using the known ABI: LastMsg() returns (address,string,uint,uint)
        address beforeSender = address(0);
        bytes32 beforeDataHash = keccak256(abi.encodePacked(""));
        uint beforeVal = 0;
        uint beforeTime = 0;
        bool hasLog = (logAddr != address(0));
        if (hasLog) {
            (address a, string memory d, uint v, uint t) = LogFileInterface(logAddr).LastMsg();
            beforeSender = a;
            beforeDataHash = keccak256(bytes(d));
            beforeVal = v;
            beforeTime = t;
        }

        bool reverted;
        try c.Put{value: amount}(lockTime) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read LastMsg after the call if Log exists
        address afterSender = address(0);
        bytes32 afterDataHash = keccak256(abi.encodePacked(""));
        uint afterVal = 0;
        uint afterTime = 0;
        if (hasLog) {
            (address a2, string memory d2, uint v2, uint t2) = LogFileInterface(logAddr).LastMsg();
            afterSender = a2;
            afterDataHash = keccak256(bytes(d2));
            afterVal = v2;
            afterTime = t2;
        }

        // General assertion as described in the summary:
        // If Put did not revert and a Log is set, LastMsg must have been updated to (sender=this, val=amount, data="Put", time>=beforeTime).
        // If Put did revert and a Log is set, LastMsg must be unchanged.
        // If no Log is set (logAddr==0), we cannot observe LastMsg so require that revert==true (because calling AddMessage on zero address would revert)
        // However, we must express a single assert over parameters and observed values.

        if (hasLog) {
            // when log exists, either reverted==false and new LastMsg matches, or reverted==true and LastMsg unchanged
            assert((!reverted && afterSender == address(this) && afterVal == amount && afterDataHash == keccak256(abi.encodePacked("Put")) && afterTime >= beforeTime)
                   || (reverted && afterSender == beforeSender && afterVal == beforeVal && afterDataHash == beforeDataHash && afterTime == beforeTime));
        } else {
            // no Log set: AddMessage call will fail; thus Put must have reverted
            assert(reverted);
        }
    }

    // Minimal interface to call LogFile's public getter LastMsg. This is not a full redeclaration of LogFile behavior.
    // Declaring an interface type is allowed and does not conflict with the existing contract.
    abstract contract LogFileInterface {
        function LastMsg() public view virtual returns (address, string memory, uint, uint);
    }

    receive() external payable {}
}

